import math

def raizes_reais(a, b, c):
    if a == 0:
        return []

    delta = b ** 2 - 4 * a * c

    if delta < 0:
        return []
    elif delta == 0:
        return [-b / (2 * a)]
    else:
        raiz_delta = math.sqrt(delta)
        x1 = (-b + raiz_delta) / (2 * a)
        x2 = (-b - raiz_delta) / (2 * a)
        return sorted([x1, x2])

